 async function sourcePixels(progress){return page.$eval('.nw-motion-dialog iframe',(f,progress)=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].set(progress);const node=d.querySelector('[data-nw-stream-slot]'),c=d.querySelector('.nw-stripe-surface'),density=c.width/node.offsetParent.clientWidth;if(!node.__nwMotionInstances.length)throw new Error('The sampled source must be present');return node.__nwMotionInstances.filter(t=>Math.max(...t.polygon.map(p=>p.x))-Math.min(...t.polygon.map(p=>p.x))>4&&Math.max(...t.polygon.map(p=>p.y))-Math.min(...t.polygon.map(p=>p.y))>4).map(t=>{const poly=t.polygon,x=poly.reduce((s,p)=>s+p.x,0)/poly.length,y=poly.reduce((s,p)=>s+p.y,0)/poly.length;return {pixel:Array.from(c.getContext('2d').getImageData(Math.floor(x*density),Math.floor(y*density),1,1).data)};});},progress);}
